s3_bucket <- "chrr-s3-demo"
s3_object <- "raw_data/ACS/2024/S0802.pq"
vars_object <- "raw_data/ACS/2024_vars_S.pq"
s3_endpoint <- "web.s3.wisc.edu"

ui <- page_sidebar(
  title = "ACS-5 2025 Table S0802. Means of Transportation to Work by Selected Characteristics",
  theme = bs_theme(version = 5),
  sidebar = sidebar(
    selectInput(
      inputId = "x_var",
      label = "X variable",
      choices = variable_choices,
      selected = variable_choices[[2]]
    ),
    selectInput(
      inputId = "y_var",
      label = "Y variable",
      choices = variable_choices,
      selected = variable_choices[[3]]
    )
  ),
  card(
    full_screen = TRUE,
    card_header("Scatterplot"),
    plotOutput("scatterplot", height = 500)
  ),
  card(
    full_screen = TRUE,
    card_header("Variable definitions"),
    div(
      style = "max-height: 300px; overflow-y: auto;",
      tableOutput("variable_definitions")
    )
  )
)

server <- function(input, output, session) {
  thematic::thematic_shiny()

  s3_fs <- S3FileSystem$create(
    anonymous = TRUE,
    scheme = "https",
    endpoint_override = s3_endpoint
  )

  dataset <- open_dataset(
      sources = file.path(s3_bucket, s3_object),
      filesystem = s3_fs,
      format = "parquet"
    )

  variable_definitions <- open_dataset(
    sources = file.path(s3_bucket, vars_object),
    filesystem = s3_fs,
    format = "parquet"
  ) |>
    filter(variable %in% variable_choices) |>
    select(variable, label) |>
    arrange(variable) |>
    collect()

  plot_data <- reactive({
    req(input$x_var, input$y_var)

    dataset |>
      select(all_of(c(input$x_var, input$y_var))) |>
      filter(
        !is.na(.data[[input$x_var]]),
        !is.na(.data[[input$y_var]])
      ) |>
      collect()
  })

  output$scatterplot <- renderPlot({
    ggplot(
      plot_data(),
      aes(x = .data[[input$x_var]], y = .data[[input$y_var]])
    ) +
      geom_point(alpha = 0.7)
  })

  output$variable_definitions <- renderTable({
    variable_definitions
  })
}

shinyApp(ui, server)
